local util           = require 'XLua.util'
local CoWait         = CS.Engine.Lib.CoWait
local KTool          = CS.Engine.Lib.KTool
local UIModule       = CS.Engine.UI.UIModule
local KCookie        = CS.Engine.Lib.KCookie
local BehaviourAction      = CS.Engine.Lib.BehaviourAction

---@type ActivityUtils
local ActivityUtils  = import("Game.Activity.ActivityUtils")
local NAME           = "UIActivityMultipleSignDialog"

---@class UIActivityMultipleSignDialog
---@field BtnRoleNameNode               	UnityEngine.RectTransform
---@field TxtPlayState                  	UnityEngine.RectTransform
---@field LoopListCell                  	SuperScrollView.LoopListView2
---@field TxtTime                       	TMPro.TextMeshProUGUI
---@field ImgTitleName                  	UnityEngine.UI.RawImage
---@field ImgRole                        	UnityEngine.RectTransform
---@field Text                          	UnityEngine.UI.Text
---@field OneAloneCell                  	UnityEngine.RectTransform
---@field BossDrawingNode                  	Game.Native.Common.DrawingNode
local UIActivityMultipleSignDialog = Class(NAME)
function UIActivityMultipleSignDialog:__init()
    self.multipleSignData = nil
end

function UIActivityMultipleSignDialog:__delete()
    self.controller = nil
    self.multipleSignData = nil
end

function UIActivityMultipleSignDialog:Awake()
    local behaviourAction = KTool.GetOrAddComponent(self.controller.gameObject, typeof(BehaviourAction))
    if behaviourAction then
        behaviourAction.OnEnableAction = Bind(self, self.OnEnable)
        self.behaviourAction = behaviourAction
    end
    
    -- init data
    local argument = self.controller.Argument
    if not argument or isNull(argument.parameters) then
        return
    end
    
    self:InitView(argument.parameters)
end

function UIActivityMultipleSignDialog:OnEnable()
    KTool.SetActive(self.BtnRoleNameNode, false)
end


function UIActivityMultipleSignDialog:Refresh(activityDojo, signData)
    self.activityDt   = activityDojo
    self.activityUuid = checkInt(activityDojo.id)
    self.multipleSignData = checkTable(signData.accumulativePay)
    self.multipleSignConf = checkTable(signData.accumulativePayConf)
    self.animMapList  = {}
    self:initBindEvent()
    -- update view
    self:RefreshView()
    self:RefreshCurrencyBarInfo()
end

function UIActivityMultipleSignDialog:RefreshCurrencyBarInfo()
    ActivityUtils.RefreshNavigatorGoods(checkTable(self.multipleSignConf).itemId)
end

function UIActivityMultipleSignDialog:initBindEvent()
    local oneAloneEnv = CfUtils.GetLuaScr(self.OneAloneCell, "Game.UI.ActivityMainDialog.UIActivityMultipleSignCellNode")
    if oneAloneEnv then
        oneAloneEnv:SetBtnAction(function(rewardId, rewardIndex, cellIndex)
            self:OnClickGetBtnHandler(rewardId, rewardIndex, cellIndex)
        end)
    end
    SetButtonAction(self.TxtPlayState, function()
        if self.multipleSignConf then
            CfUtils.ShowModuleToast(self.multipleSignConf.ruleId)
        end
    end)
end

function UIActivityMultipleSignDialog:InitView(data)
    if not data.activityDt or not data.signDt then
        return
    end

    self:Refresh(data.activityDt, data.signDt)
end

function UIActivityMultipleSignDialog:RefreshView()
    if not self.activityDt or next(self.activityDt) == nil then
        return
    end

    -- update reward
    self:updateRewardInfo()

    -- update role
    self:updateRoleInfo()

    -- update view
    CfUtils.FillText(self.TxtTime, ActivityUtils.ConventActivityDurationTime(self.activityDt.startTime, self.activityDt.endTime))
    CfUtils.FillText(self.Text, string.trim(self.activityDt.detail) ~= "" and self.activityDt.detail or "TO BE CONTINUE")

    local titleImgUrl = checkString(self.activityDt.titleImage)
    if string.len(titleImgUrl) > 0 then
        CfUtils.FillWebRawImage(self.ImgTitleName, titleImgUrl)
    end

    KTool.SetActive(self.TxtPlayState, checkInt(self.multipleSignConf.ruleId) > 0)
end

function UIActivityMultipleSignDialog:GetItemShowNum()
    return checkInt(self.itemShowNum)
end

function UIActivityMultipleSignDialog:updateRoleInfo()
    if not self.multipleSignConf or next(self.multipleSignConf) == nil then
        return
    end

    local goodsType = GoodsUtils.GetIdType(self.multipleSignConf.rewardId)
    local isCardOrSkin = goodsType == Constants.IDType.CharacterCard or goodsType == Constants.IDType.CardSkin
    if checkString(self.multipleSignConf.rewardImg) ~= '' then
        KTool.SetActive(self.ImgRole, true)
        CfUtils.FillImage(self.ImgRole, ActivityUtils.GetImageFullPath(self.multipleSignConf.rewardImg))
    end
    
    if isCardOrSkin then
        KTool.SetActive(self.ImgRole, true)
        KTool.SetActive(self.BtnRoleNameNode, true)
        ---@type CommonBtnRoleNameNode
        local env = CfUtils.GetLuaScr(self.BtnRoleNameNode, "Game.UI.Common.CommonBtnRoleNameNode")
        if env then
            env:RefreshSelf(self.multipleSignConf.rewardId, nil, function ()
                KCookie.Set(Constants.UICacheDataKeys.UI_ACTIVITY_MAIN_SELECTED_ACTIVITY_ID, self.activityUuid)
            end, true)
        end
        if goodsType == Constants.IDType.CharacterCard  then
            local vo = CardConfMgr:GetInstance():GetCardByRefId(self.multipleSignConf.rewardId)
            self.BossDrawingNode:Execute(vo.defaultSkin)
        else     
            self.BossDrawingNode:Execute(self.multipleSignConf.rewardId)
        end
        
    end
end

function UIActivityMultipleSignDialog:updateRewardInfo()
    if not self.multipleSignData or next(self.multipleSignData) == nil then
        return
    end

    -- find curDay
    self.curDay = #self.multipleSignData
    for _, signData in ipairs(self.multipleSignData) do
        if checkInt(signData.status) < Constants.GetStatus.Can then
            break
        end
        self.curDay = checkInt(signData.accumulativeLoginNum)
    end

    -- update list
    local totalCount     = #self.multipleSignData - 1
    local normalCount    = totalCount
    local curDayDt       = self.multipleSignData[self.curDay]
    self.cellTargetIndex = checkInt(curDayDt.status) == Constants.GetStatus.Has and self.curDay or self.curDay - 1
    if not self.LoopListCell.IsListViewInit then
        self.LoopListCell:InitListView(normalCount, Bind(self, self.OnGetItemByIndex), {mTargetIndex = self.cellTargetIndex })
    else
        self.LoopListCell:MovePanelToItemIndex(self.cellTargetIndex )
    end

    -- update max reward
    local oneAloneEnv = CfUtils.GetLuaScr(self.OneAloneCell, "Game.UI.ActivityMainDialog.UIActivityMultipleSignCellNode")
    if oneAloneEnv then
        oneAloneEnv:RefreshSelf(self.multipleSignData[normalCount + 1], self.curDay)
    end
end

function UIActivityMultipleSignDialog:OnGetItemByIndex(listView, index)
    if index < 0 then
        return nil
    end
    local cell = listView:NewListViewItem("Cell")
    self:UpdateListViewItem(index, cell)
    return cell
end

function UIActivityMultipleSignDialog:OnClickGetBtnHandler(rewardId, rewardIndex, cellIndex)
    rewardId    = checkInt(rewardId)
    rewardIndex = checkInt(rewardIndex)
    cellIndex   = checkInt(cellIndex)
    GameUtils.Request(
        Interfaces.ActivityDrawAccumulativeLogin,
        {activityUuid = self.activityUuid, rewardId = rewardId},
        function(request, response)
            if checkInt(response.errCode) == 0 then

                -- update reward
                local data = response.data
                GoodsUtils.DrawRewards(data.rewards, true)
                UIModule.OpenDialog(
                        {
                            id = Constants.UITypeIds.UICommonRewardPop,
                            parameters = { rewards = data.rewards }
                        }
                )

                ActivityUtils.UpdateActivityMainRedPointState(self.activityUuid, -1)
                -- update data
                if cellIndex < 0 then
                    self.multipleSignData[#self.multipleSignData].status = Constants.GetStatus.Has
                    local oneAloneEnv = CfUtils.GetLuaScr(self.OneAloneCell, "Game.UI.ActivityMainDialog.UIActivityMultipleSignCellNode")
                    if oneAloneEnv then
                        oneAloneEnv:RefreshSelf(self.multipleSignData[#self.multipleSignData], self.curDay)
                    end
                else
                    self.multipleSignData[cellIndex + 1].status = Constants.GetStatus.Has
                    self.LoopListCell:RefreshItemByItemIndex(cellIndex)
                end
            end
        end)
end

function UIActivityMultipleSignDialog:UpdateListViewItem(cellIndex, cellNode)
    local nodeEnv = CfUtils.GetLuaScr(cellNode, "Game.UI.ActivityMainDialog.UIActivityMultipleSignCellNode")
    if nodeEnv then
        if self:GetItemShowNum() <= 0 then
            local cellSizeH  = cellNode.CachedRectTransform.rect.height + cellNode.Padding
            local totalNum   = self.LoopListCell.ItemTotalCount
            self.itemShowNum = math.ceil(self.LoopListCell.ViewPortHeight / cellSizeH)
            self.animInitPos = math.max(0, math.min(self.cellTargetIndex, totalNum - self:GetItemShowNum()))
            self.animEndPos  = math.min((self:GetItemShowNum() + self.cellTargetIndex), totalNum)
        end

        if not self.animMapList[cellIndex + 1] and cellIndex <=  self.animEndPos and cellIndex >= self.animInitPos then
            self.animMapList[cellIndex + 1] = true
            nodeEnv:PlayFadeInAnim(cellIndex - self.animInitPos)
        else
            nodeEnv:PlayInitAnim()
        end

        nodeEnv:RefreshSelf(self.multipleSignData[cellIndex + 1], self.curDay, cellIndex)
        nodeEnv:SetBtnAction(function(rewardId, rewardIndex, cellIndex)
            self:OnClickGetBtnHandler(rewardId, rewardIndex, cellIndex)
        end)
    end
end

function UIActivityMultipleSignDialog:OnDestroy()
    self.controller = nil --删除lua层引⽤用到的c#对象,否则不不会产⽣生c# gc回收到对象
    self:Delete()
    self = nil --lua层的gc需要 
end

return UIActivityMultipleSignDialog